T["Automatic: every 10 minutes and on logout Oasis stores a snapshot in the saved variables (WTF/Account/<account>/SavedVariables/Oasis.lua). The program Tools/oasis_export.py reads the file, turns it into JSON and can send it to your web page. Addons have no internet access - this is the safe way."] = "自動：Oasis每10分鐘及登出時在儲存的變數中儲存快照（WTF/Account/<賬號>/SavedVariables/Oasis.lua）。程式Tools/oasis_export.py讀取該檔案，轉換為JSON，並可傳送到你們的網頁介面。外掛無法聯網 - 這是安全的方式。"
