T["The guild leadership names raid leaders under Crown > Modules > Raids & Loot. In a running raid, the raid leader and assistants count too."] = "公會管理在王冠 > 模組 > 團隊與戰利品中指定團隊領袖。進行中的團隊副本中，團隊領袖和助理也算。"
T["The guild leadership names raid leaders under Crown > Modules > Raids & Loot. In a running raid, the raid leader counts too."] = "公會管理在王冠 > 模組 > 團隊與戰利品中指定團隊領袖。進行中的團隊副本中，團隊領袖也算。"
