T["Stats: +healing, intellect, spirit, mp5;Weapon: staff or one-hander + off-hand with healing;Healing: Rejuvenation and Regrowth ahead, Healing Touch for big hits;Tip: Innervate for mana, Rebirth for fallen healers"] = "屬性：+治療、智力、精神、法力回覆;武器：法杖或單手武器 + 帶治療的副手;治療：預先回春術和癒合，大傷害用治療之觸;提示：用啟用回藍，用復生救倒下的治療"
T["Stats: +healing, intellect, spell crit (Illumination refunds mana), mp5;Weapon: one-hander + off-hand/shield with healing;Healing: Flash of Light for small damage, Holy Light (low rank) for big hits;Tip: hand out blessings, Divine Protection when you pull aggro"] = "屬性：+治療、智力、法術暴擊（啟迪返還法力）、法力回覆;武器：單手武器 + 帶治療的副手/盾牌;治療：小傷害用聖光閃現，大傷害用聖光術（低階）;提示：分發祝福，被攻擊時用聖佑術"
T["Stats: +healing, mp5, intellect - spirit does little;Weapon: one-hander + shield with healing;Healing: Chain Heal for groups, Healing Wave (low rank) for the tank;Tip: drop Mana Spring Totem, Earth Shield on the tank"] = "屬性：+治療、法力回覆（MP5）、智力 - 精神作用不大;武器：單手武器 + 帶治療的盾牌;治療：團隊用治療鏈，坦克用治療波（低階）;提示：放置法力之泉圖騰，給坦克上大地之盾"
T["Stats: +healing, spirit (Meditation: regen while casting), intellect, mp5;Weapon: staff or one-hander + off-hand with healing, wand;Healing: Renew and Power Word: Shield ahead, Greater Heal (low rank) for the tank;Tip: Prayer of Healing for the group, Fade on aggro"] = "屬性：+治療、精神（冥想：施法時也回覆）、智力、法力回覆;武器：法杖或單手武器 + 帶治療的副手、魔杖;治療：預先恢復和真言術：盾，坦克用強效治療術（低階）;提示：隊伍用治療禱言，仇恨過高時用漸隱術"
T["Stats: armor (bear form multiplies it), stamina, agility (dodge + armor);Weapon: damage doesn't matter - only the stats (staff/polearm with stamina);Rotation: Maul, Swipe for packs, Demoralizing Roar;Tip: strength for more threat, Enrage to start"] = "屬性：護甲（熊形態大幅提升）、耐力、敏捷（躲閃 + 護甲）;武器：對傷害無影響 - 只看屬性（帶耐力的法杖/長柄武器）;迴圈：槌擊、揮擊打群體、挫志咆哮;提示：力量增加威脅，開場用激怒"
T["Stats: strength (1 point = 2 AP), agility (AP + crit), crit, hit up to +9 %;Weapon: damage doesn't matter - only the stats;Rotation: Claw/Shred for combo points, then Ferocious Bite;Tip: powershift (recast form) for energy, open from stealth"] = "屬性：力量（1點 = 2攻擊強度）、敏捷（攻擊強度 + 暴擊）、暴擊、命中至+9 %;武器：對傷害無影響 - 只看屬性;迴圈：爪擊/撕碎攢連擊點，然後兇猛撕咬;提示：用變形重置（重新變形）回能量，從潛行中突襲"
T["Stats: strength (1 point = 2 AP), crit (procs Flurry = faster swings), hit up to +9 %;Weapon: slow two-hander - Windfury procs per swing, so slower = more damage;Rotation: Windfury Weapon, Stormstrike, Earth Shock;Tip: Strength of Earth and Windfury Totem for the group"] = "屬性：力量（1點 = 2攻擊強度）、暴擊（觸發亂舞 = 攻速更快）、命中至+9 %;武器：慢速雙手武器 - 風怒按每次攻擊觸發，越慢傷害越高;迴圈：風怒武器、風暴打擊、地震術;提示：為隊伍放置大地之力圖騰和風怒圖騰"
T["Stats: strength (1 point = 2 AP), crit, hit up to +9 %;Weapon: slow two-hander - seals and Judgement scale per swing;Rotation: Seal of Righteousness/Command, Judgement, reapply seal;Tip: Consecration only with enough mana, Blessing of Might on yourself"] = "屬性：力量（1點 = 2攻擊強度）、暴擊、命中至+9 %;武器：慢速雙手武器 - 聖印和審判按每次攻擊生效;迴圈：正義聖印/命令聖印、審判、重新施放聖印;提示：法力充足時才用奉獻，給自己上力量祝福"
T["Stats: hit up to +9 %, agility (1 AP, ~29 = 1 % crit), AP, crit;Weapon: Combat = fast off-hand, slow main hand (Sinister Strike); daggers for Backstab;Rotation: build combo points, keep Slice and Dice up, then Eviscerate;Tip: dual wielding misses white hits more often - hit matters most"] = "屬性：命中至+9 %、敏捷（1攻擊強度，約29 = 1 %暴擊）、攻擊強度、暴擊;武器：戰鬥 = 快速副手、慢速主手（邪惡攻擊）; 刺殺用匕首;迴圈：攢連擊點、保持切割、然後剔骨;提示：雙持時普通攻擊更容易未命中 - 命中最重要"
T["Stats: hit up to +9 %, agility (2 ranged AP, ~53 = 1 % crit), AP, intellect;Weapon: slow ranged weapon (big damage per shot), melee weapon for stats;Rotation: Hunter's Mark, Auto Shot, Aimed Shot/Multi-Shot in between;Tip: feed your pet and keep it happy, Freezing Trap (square) for control"] = "屬性：命中至+9 %、敏捷（2遠端攻擊強度，約53 = 1 %暴擊）、攻擊強度、智力;武器：慢速遠端武器（每發傷害高）、帶屬性的近戰武器;迴圈：獵人印記、自動射擊、穿插瞄準射擊/多重射擊;提示：餵養寵物並保持快樂，冰凍陷阱（方塊）用於控制"
T["Stats: hit up to +9 %, strength (1 point = 2 AP), crit (~20 agility = 1 %);Weapon: slow two-hander (Mortal Strike, Heroic Strike scale per swing);Rotation: build rage, Mortal Strike / Bloodthirst, Whirlwind, spare rage into Heroic Strike;Tip: Battle Shout before the pull, Execute below 20 % health"] = "屬性：命中至+9 %、力量（1點 = 2攻擊強度）、暴擊（約20敏捷 = 1 %）;武器：慢速雙手武器（致死打擊、英勇打擊按每次攻擊生效）;迴圈：積攢怒氣、致死打擊/嗜血、旋風斬、多餘怒氣用英勇打擊;提示：戰前用戰鬥怒吼，20 %血量以下用斬殺"
T["Stats: defense (440 = crit immune vs bosses at 60), stamina, armor, block;Weapon: one-hander + shield, fast weapon = more rage;Rotation: Shield Slam/Revenge, Sunder Armor on the target, Heroic Strike with high rage;Tip: hit helps so Taunt and abilities don't miss"] = "屬性：防禦（60級440防禦免疫首領暴擊）、耐力、護甲、盾牌格擋;武器：單手武器 + 盾牌，快速武器 = 更多怒氣;迴圈：盾牌猛擊/復仇、對目標破甲、怒氣多時用英勇打擊;提示：命中有助於嘲諷和技能不被未命中"
T["Stats: defense, stamina, armor, then spell damage for more threat;Weapon: one-hander (ideally spell damage) + shield;Rotation: Righteous Fury on, Consecration for packs, keep Holy Shield up;Tip: mana is tight - use Seal of Wisdom or some intellect"] = "屬性：防禦、耐力、護甲，然後法術傷害以提高威脅;武器：單手武器（最好帶法術傷害）+ 盾牌;迴圈：開啟正義之怒、群體用奉獻、保持神聖之盾;提示：法力緊張 - 帶上智慧聖印或智力"
T["Stats: spell damage, spell crit (Elemental Focus saves mana), intellect, mp5;Weapon: one-hander + shield/off-hand with spell damage;Rotation: spam Lightning Bolt, Chain Lightning on packs, Flame Shock;Tip: spell hit up to +16 % in raids, Mana Spring Totem against oom"] = "屬性：法術傷害、法術暴擊（元素集中節省法力）、智力、法力回覆;武器：單手武器 + 帶法術傷害的盾牌/副手;迴圈：狂按閃電箭、群體用閃電鏈、烈焰震擊;提示：團隊中法術命中至+16 %，用法力之泉圖騰防止空藍"
T["Stats: spell damage, spell crit, intellect, spell hit up to +16 % in raids;Weapon: staff or one-hander + off-hand with spell damage;Rotation: Moonfire + Insect Swarm, then Wrath or Starfire;Tip: Innervate yourself when mana runs low"] = "屬性：法術傷害、法術暴擊、智力、團隊中法術命中至+16 %;武器：法杖或單手武器 + 帶法術傷害的副手;迴圈：月火術 + 蟲群，然後憤怒或星火術;提示：法力緊張時給自己用啟用"
T["Stats: spell damage, spell hit up to +16 % (raid), stamina, intellect;Weapon: staff or dagger + off-hand with spell damage, wand for leftover mana;Rotation: Corruption + curse, then Shadow Bolt; Life Tap instead of drinking;Tip: stamina pays off twice (Life Tap, Voidwalker/Soul Link)"] = "屬性：法術傷害、法術命中至+16 %（團隊）、耐力、智力;武器：法杖或匕首 + 帶法術傷害的副手，魔杖用於剩餘法力;迴圈：腐蝕術 + 詛咒，然後暗影箭; 用生命分流代替喝水;提示：耐力有雙重收益（生命分流、虛空行者/靈魂連結）"
T["Stats: spell damage, spell hit up to +16 % (raid), spirit for mana;Weapon: staff or one-hander + off-hand with spell damage;Rotation: Shadow Word: Pain, Mind Blast, Mind Flay;Tip: stay in Shadowform, Vampiric Embrace heals the group"] = "屬性：法術傷害、法術命中至+16 %（團隊）、精神回法力;武器：法杖或單手武器 + 帶法術傷害的副手;迴圈：暗言術：痛、心靈震爆、精神鞭笞;提示：保持暗影形態，吸血鬼的擁抱治療隊伍"
T["Stats: spell damage, then spell hit up to +16 % (raid bosses), intellect, spell crit;Weapon: staff with spell damage, plus a wand for leftover mana;Rotation: spam Frostbolt or Fireball, Evocation when out of mana;Leveling: intellect and spirit = less downtime, sheep (moon) in groups"] = "屬性：法術傷害，然後法術命中至+16 %（團隊首領）、智力、法術暴擊;武器：帶法術傷害的法杖，加一根魔杖用於剩餘法力;迴圈：狂按寒冰箭或火球術，空藍時用喚醒;升級：智力和精神 = 更少休息，組隊時用變羊（月亮）"
