T["Shows BETTER / WORSE / CAN'T EQUIP with effect (DPS, health, armor) and a stats table. Blizzard's comparison then only appears with Shift. If nesUI is loaded with its own comparison, Oasis shows nothing (avoids doubles) - turn it off there with /nes vergleich."] = "顯示更好/更差/無法穿戴及影響（DPS、生命值、護甲）和屬性表。暴雪的比較需按Shift才顯示。如已載入自帶比較的nesUI，Oasis不顯示（否則重複）- 可在那裡用/nes vergleich關閉。"
T["Shows better / worse / can't equip with effect (DPS, health, armor) and a stats table. Blizzard's comparison then only appears with Shift. If nesUI with its own comparison is loaded, Oasis shows nothing (otherwise doubled) - turn it off there with /nes vergleich."] = "顯示更好/更差/無法穿戴及影響（DPS、生命值、護甲）和屬性表。暴雪的比較需按Shift才顯示。如已載入自帶比較的nesUI，Oasis不顯示（否則重複）- 可在那裡用/nes vergleich關閉。"
T["Shows dungeon loot in your level range that beats your equipped item."] = "顯示你等級範圍地下城中比你已裝備的更好的戰利品。"
T["Shows a gem from Oasis rank 30 and a shimmering name from rank 70 in the Oasis guild chat"] = "在Oasis公會聊天中，Oasis等級30起顯示寶石，70起顯示閃光名字"
T["Shows the level range of each zone"] = "顯示區域的等級範圍"
T["Shows a notice as soon as a guildmate creates a new event"] = "公會中有人建立新活動時顯示提示"
T["Shows typical Barrens chat lines in general chat now and then while in the Barrens - Chuck Norris, Mankrik's wife ... Only for you, nothing is sent."] = "在貧瘠之地的綜合頻道中不時顯示經典段子 - 查克·諾里斯、曼克里克的老婆……僅你可見，不會傳送。"
T["Shows in the item tooltip who reserved the item for an upcoming event"] = "在物品滑鼠提示中顯示誰為即將到來的活動預定了該物品"
