T["1.  Keep the combat log on (Settings > Areas > Combat board, on by default).\n2.  After playing, double-click ImportCrits.bat in the Oasis folder.\n3.  /reload in game - your highest crit shows here and is shared with the guild."] = "1.  保持戰鬥日誌開啟（設定 > 模組 > 戰鬥排行榜，預設開啟）。\n2.  遊戲結束後，雙擊 Oasis 資料夾中的 ImportCrits.bat。\n3.  在遊戲中 /reload - 你的最高暴擊會顯示在這裡並與公會共享。"
