T["All members with rank, level and Oasis version. Right-click a row: change rank."] = "所有成員及其會階、等級和 Oasis 版本。右鍵點選一行：更改會階。"
T["All fonts under the SIL Open Font License 1.1"] = "所有字型均採用 SIL Open Font License 1.1"
T["All: Burning Adrenaline: run out of the raid AT ONCE (you are about to die).\nAll: Full resources at the start - use everything.\nTank: Set a tank order (Adrenaline on the tank).\nDD: Not in front of or behind the dragon."] = "All: 燃燒刺激：立刻跑出團隊（你馬上就會死）。\nAll: 開場資源全滿 - 全力輸出。\nTank: 安排坦克順序（燃燒刺激會點坦克）。\nDD: 不要站在龍的正面或背後。"
T["All: Do not let the 8 Firesworn die near the raid (explosion).\nTank: Each add tank pulls their Firesworn away, warlocks banish.\nHealer: Dispel, keep an eye on the add tanks.\nDD: Garr first, adds only when called."] = "All: 不要讓 8 個火誓者死在團隊附近（爆炸）。\nTank: 每個小怪坦克把自己的火誓者拉開，術士放逐。\nHealer: 驅散，留意小怪坦克。\nDD: 先打加爾，小怪聽指揮再打。"
T["All: Tank the two Core Ragers away from the boss, do not kill them.\nTank: Swap the Golemagg tank when Magma Splash stacks too high.\nDD: Only on Golemagg."] = "All: 把兩隻熔火怒犬拉離首領坦住，不要擊殺。\nTank: 熔岩飛濺疊得太高時更換古雷曼格坦克。\nDD: 只打古雷曼格。"
T["All: The 4 priests first, they heal each other.\nTank: Keep Sulfuron and the priests apart.\nDD: Interrupt! Stop the priests' Dark Mending."] = "All: 先殺 4 個牧師，它們會互相治療。\nTank: 把薩弗隆和牧師分開。\nDD: 打斷！阻止牧師的黑暗治癒。"
T["All: Fire protection! Wrath of Ragnaros knocks melee back - then get back in.\nAll: Sons phase (after 3 min or when he submerges): kill all Sons of Flame.\nTank: Second tank ready when the first is knocked away.\nHealer: Spread out, ranged not too close (Lava Burst).\nDD: Melee: keep mana under control, ranged keep your distance."] = "All: 火焰抗性！拉格納羅斯之怒會擊退近戰 - 之後再回去。\nAll: 烈焰之子階段（3 分鐘後或他下潛時）：擊殺所有烈焰之子。\nTank: 第二坦克隨時準備接手被擊飛的主坦克。\nHealer: 分散站位，遠端不要靠太近（熔岩爆裂）。\nDD: 近戰：控制好法力，遠端保持距離。"
T["All: Flame Buffet stacks - ranged behind pillars to let it drop.\nTank: Two tanks behind pillars, Wing Buffet knocks back.\nDD: Onyxia Scale Cloak required."] = "All: 烈焰打擊會疊加 - 遠端躲到柱子後消層。\nTank: 兩個坦克躲在柱子後，龍翼打擊會擊退。\nDD: 必須裝備奧妮克希亞鱗片披風。"
T["All: Remove Gehennas' Curse (reduced healing) at once.\nAll: Get out of the Rain of Fire.\nTank: Tank the two Flamewakers apart.\nDD: Flamewakers first, then Gehennas."] = "All: 立刻解除基赫納斯的詛咒（治療效果降低）。\nAll: 離開火焰之雨。\nTank: 把兩個烈焰行者分開坦。\nDD: 先殺烈焰行者，再打基赫納斯。"
T["All: Remove Lucifron's Curse and Impending Doom at once (mages/druids, priests/paladins).\nTank: Tank the two guards apart - mind control!\nHealer: Spread out, dispel mind-controlled players.\nDD: Guards first, then Lucifron."] = "All: 立刻解除魯西弗隆的詛咒和末日降臨（法師/德魯伊、牧師/聖騎士）。\nTank: 把兩個護衛分開坦 - 小心精神控制！\nHealer: 分散站位，驅散被精神控制的玩家。\nDD: 先殺護衛，再打魯西弗隆。"
T["All: Living Bomb: run out of the raid AT ONCE!\nAll: Inferno - away from the boss, dispel Ignite Mana.\nTank: Hold the middle, step out briefly on Inferno.\nDD: Melee back off on Inferno."] = "All: 活體炸彈：立刻跑出團隊！\nAll: 地獄火 - 遠離首領，驅散點燃法力。\nTank: 守住中間，地獄火時短暫離開。\nDD: 地獄火時近戰後撤。"
T["All: Watch the guards' magic reflection/damage shield - stop damage then.\nTank: One guard per tank, mages sheep the elite guards.\nDD: Healer guards (Flamewaker Healer) first."] = "All: 注意護衛的魔法反射/傷害護盾 - 此時停止輸出。\nTank: 每個坦克一個護衛，法師變羊精英護衛。\nDD: 先殺治療護衛（Flamewaker Healer）。"
T["All: Never stand in front of or behind Onyxia (breath and tail sweep).\nAll: Phase 2 (65%): dodge fireballs, stay out of the cave entrances.\nAll: Phase 3 (40%): fear - Fear Ward/Tremor Totem ready, avoid the lava cracks.\nTank: Onyxia sideways at the wall, head away from the raid.\nTank: Phase 2: pick up the whelps. Phase 3: get aggro back at once.\nHealer: Tank has priority, spread out in phase 2.\nDD: Wait for 3 attacks of the tank. Phase 2: whelps first."] = "All: 絕不要站在奧妮克希亞的正面或背後（吐息和掃尾）。\nAll: 第 2 階段（65%）：躲開火球，不要進入洞穴入口。\nAll: 第 3 階段（40%）：恐懼 - 準備好防護恐懼結界/戰慄圖騰，避開熔岩裂縫。\nTank: 把奧妮克希亞側向貼牆，頭部背對團隊。\nTank: 第 2 階段：收攏雛龍。第 3 階段：立刻拉回仇恨。\nHealer: 坦克優先，第 2 階段分散站位。\nDD: 等坦克攻擊 3 次再打。第 2 階段：先殺雛龍。"
T["All: Panic - Fear Ward/Tremor Totem, hunters: Tranquilizing Shot on Frenzy.\nAll: Get out of the lava fire on the ground.\nTank: Magmadar with his back to the raid.\nDD: Ranged spread out at the back."] = "All: 恐慌 - 防護恐懼結界/戰慄圖騰，獵人：狂暴時使用寧神射擊。\nAll: 離開地上的熔岩火焰。\nTank: 讓瑪格曼達背對團隊。\nDD: 遠端在後方分散站位。"
T["All: Phase 1: dragonkin from both sides, watch the class calls.\nAll: Phase 3 (20%): the skeletons rise again - kill them again.\nTank: Nefarian at the wall, fear - Fear Ward.\nHealer: Class call for priests: healing hurts - be careful.\nDD: Hunters/warriors: watch the class calls (weapons gone, stance)."] = "All: 第 1 階段：龍人從兩側出現，注意職業點名。\nAll: 第 3 階段（20%）：骷髏再次復活 - 再殺一遍。\nTank: 把奈法利安拉到牆邊，恐懼 - 防護恐懼結界。\nHealer: 牧師職業點名：治療會造成傷害 - 小心。\nDD: 獵人/戰士：注意職業點名（武器損壞、姿態）。"
T["All: Phase 1: destroy the eggs (mind control via the orb), pick up the adds.\nAll: After all eggs: boss in the room - Fire Nova.\nTank: Gather the adds at the stairs.\nDD: Mages and dragonkin first."] = "All: 第 1 階段：摧毀龍蛋（透過寶珠精神控制），接住小怪。\nAll: 龍蛋全毀後：首領進入房間 - 火焰新星。\nTank: 在樓梯處聚攏小怪。\nDD: 先殺法師和龍人。"
T["All: Frenzy - hunters: Tranquilizing Shot.\nTank: Two tanks, watch Wing Buffet.\nDD: Onyxia Scale Cloak required."] = "All: 狂暴 - 獵人：寧神射擊。\nTank: 兩個坦克，注意龍翼打擊。\nDD: 必須裝備奧妮克希亞鱗片披風。"
T["All: Shadow of Ebonroc heals the boss - the tank with the debuff swaps.\nTank: Two tanks swap on Shadow.\nDD: Onyxia Scale Cloak required."] = "All: 埃博諾克之影會治療首領 - 中了減益的坦克換坦。\nTank: 兩個坦克在中埃博諾克之影時交換。\nDD: 必須裝備奧妮克希亞鱗片披風。"
T["All: Knockback - stand against the wall.\nTank: Two tanks, aggro is split by Knock Away.\nDD: Mortal Strike on the tank: healers be prepared."] = "All: 擊退 - 貼牆站位。\nTank: 兩個坦克，擊飛會分攤仇恨。\nDD: 坦克中致死打擊：治療做好準備。"
T["All: He teleports - whoever has aggro, do not run away.\nAll: Remove Shazzrah's Curse, Arcane Explosion: melee keep your distance.\nTank: Get back on him right after every blink.\nHealer: Dispel (Deaden Magic)."] = "All: 他會傳送 - 獲得仇恨的人不要跑開。\nAll: 解除沙斯拉爾的詛咒，魔爆術：近戰保持距離。\nTank: 每次閃現後立刻重新貼上。\nHealer: 驅散（衰減魔法）。"
T["All: Two of the five breath types per week - avoid the breath behind the corner.\nAll: Hourglass Sand for the Bronze affliction.\nTank: Tank at the gate, raid behind the corner.\nDD: Tranquilizing Shot on Frenzy."] = "All: 每週從五種吐息中出現兩種 - 躲到拐角後規避吐息。\nAll: 用沙漏之沙解除青銅減益。\nTank: 在門口坦，團隊站在拐角後。\nDD: 狂暴時使用寧神射擊。"
T["Hold Alt: all stats and scoring details. Shift: Blizzard comparison."] = "按住 Alt：全部屬性和評分詳情。Shift：暴雪對比。"
T["Release Alt: compact view. Shift: Blizzard comparison."] = "鬆開 Alt：簡潔對比。Shift：暴雪對比。"
