T["The X on the window collapses Oasis into the bar. The X on the bar closes it completely."] = "視窗上的 X 將 Oasis 收起到工具欄。工具欄上的 X 則完全關閉。"
T["The yellow exclamation mark on the icon marks this."] = "圖示上的黃色感嘆號表示這一點。"
T["That was just luck! Again!"] = "那只是運氣！再來！"
T["That's it. You can find the tour again any time under Settings > Status or with /oa rundgang."] = "就這些了。隨時可以在 設定 > 狀態 中或用 /oa rundgang 重新開啟導覽。"
T["Data"] = "資料"
T["Opaque"] = "不透明"
T["Your character"] = "你的角色"
T["Your stats: Oasis rank, badges and all counters"] = "你的資料：Oasis 等級、徽章和所有計數"
