T["The client does not let Oasis enable combat logging - please type /combatlog yourself."] = "客戶端不允許 Oasis 開啟戰鬥日誌 - 請自行輸入 /combatlog。"
T["The content of the selected area. The overview shows who is online, what is coming up and what is new."] = "所選模組的內容。概覽顯示誰線上、即將進行的事項和最新動態。"
T["The minimap button or /oa opens Oasis. The dash at the top right turns the window into a slim bar."] = "點選小地圖按鈕或輸入 /oa 開啟 Oasis。右上角的橫線可將視窗變為窄工具欄。"
T["The officer channel (/o) with history - only for ranks with officer chat permission."] = "帶歷史記錄的官員頻道（/o）- 僅限擁有官員聊天許可權的會階。"
