T["Close details"] = "關閉詳情"
T["Clear default sound for online notices"] = "上線提醒使用清晰的預設提示音"
T["Character statistics are unavailable in this client."] = "此客戶端不提供角色統計。"
T["Guild leadership has muted sound effects for you."] = "公會管理層已禁止你使用音效。"
T["The bar is there from login and stays - the X on the window only closes the window."] = "工具欄從登入起就一直顯示 - 視窗上的 X 只關閉視窗。"
T["The percentage compares the item's score for your role, not your total damage. Effects are estimates."] = "百分比比較的是物品對你職責的評分，而非你的總傷害。效果為估算值。"
T["The statistic currently provides no readable value."] = "該統計目前沒有可讀取的數值。"
