T["The full license texts are in the Oasis folder: CREDITS.txt, LICENSE and LICENSE-MIT.txt."] = "完整許可文字位於 Oasis 資料夾：CREDITS.txt、LICENSE 和 LICENSE-MIT.txt。"
T["These guild ranks (0 = guild master) may vote in the loot council."] = "這些公會會階（0 = 會長）可在拾取委員會中投票。"
